 const sources={
  1:{id:'1O3ghiyirvU',speaker:'Jack Ma',region:'China',year:2015,title:"Jack Ma: I've Had Lots Of Failures And Rejections | Davos 2015",context:'Entrevista sobre trajetória profissional, dificuldades e empreendedorismo. Observe especificamente as respostas de Jack Ma, não a voz do entrevistador.',focus:'Escolha uma resposta de Jack Ma com cerca de um minuto. Identifique o assunto, um exemplo e a conclusão. Ao estudar o relato sobre candidaturas a emprego, confira os números que ele menciona.',words:[['rejection','rejeição'],['apply for a job','candidatar-se a uma vaga'],['give up','desistir'],['entrepreneurship','empreendedorismo']],question:'No relato sobre a candidatura ao KFC, como os números se relacionam?',options:['24 candidatos; 23 aceitos; ele relata ter sido rejeitado.','23 candidatos; todos foram rejeitados.','24 candidatos; ele relata ter sido o único aceito.'],answer:0,feedback:'O relato contrasta 24 candidatos com 23 aceitos. Observe a diferença entre o número de pessoas e o resultado pessoal. É um relato de 2015, não informação atual de contratação.',reference:'https://www.weforum.org/press/2015/01/jack-ma-wants-alibaba-to-serve-2-billion-consumers/'},
  2:{id:'7sncuRJtWQI',speaker:'Sundar Pichai',region:'Índia',year:2020,title:'An Insight, An Idea with Sundar Pichai | DAVOS 2020',context:'Entrevista sobre tecnologia, oportunidades e riscos. Observe especificamente as respostas de Sundar Pichai. Sua trajetória internacional influencia sua fala; este é um exemplo individual, não um padrão de toda a Índia.',focus:'Escolha uma resposta de Sundar Pichai com cerca de um minuto. Procure uma oportunidade, um risco e uma justificativa. Para a pergunta abaixo, localize a discussão sobre inteligência artificial.',words:[['opportunity','oportunidade'],['risk','risco'],['framework','estrutura ou conjunto de diretrizes'],['make progress','avançar']],question:'Na discussão sobre IA, qual risco Pichai também destaca?',options:['Que não existam desafios ou riscos tecnológicos.','Deixar de avançar e aproveitar seu potencial de impacto positivo.','Que uma única empresa consiga resolver sozinha todos os riscos.'],answer:1,feedback:'Ele considera tanto riscos quanto oportunidades e alerta para o potencial perdido se não houver progresso. A atividade estuda a argumentação apresentada em 2020, sem tratar previsões daquela época como fatos atuais.',reference:'https://www.weforum.org/stories/2020/01/this-is-how-quantum-computing-will-change-our-lives-8a0d33657f/'}
 };
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function render(index,notes){const v=sources[index];if(!v)return '';return '<section class="card" id="authentic-listening"><div class="ey">Escuta complementar · fala real</div><h2>Ouça '+esc(v.speaker)+' em inglês</h2><p>'+esc(v.region)+' · Gravação de '+v.year+' · Publicação: World Economic Forum.</p><p>'+esc(v.context)+'</p><p>Esta entrevista tem áudio original em vídeo e não depende das vozes instaladas no Android. É diferente do diálogo fictício da lição. Não há um único sotaque por país.</p><div id="authentic-player"><button type="button" class="btn" data-authentic-load="'+index+'">Carregar entrevista original</button></div><p><a href="https://www.youtube.com/watch?v='+v.id+'" target="_blank" rel="noopener noreferrer">Abrir entrevista no YouTube ↗</a></p><p class="muted">O vídeo é carregado do YouTube somente ao tocar no botão e começa quando você toca em Reproduzir. Precisa de internet; se o player não abrir, use o link. Legendas e velocidades disponíveis são controladas pelo YouTube.</p><h3>Treino em três passagens</h3><ol><li>Ouça uma resposta sem legendas. Anote apenas a ideia principal.</li><li>Repita a mesma resposta. Use 0,75×, se disponível, e, se disponíveis, legendas em inglês para conferir palavras e números.</li><li>Volte à velocidade normal e resuma em inglês, sem imitar o sotaque.</li></ol><p>'+esc(v.focus)+'</p><h3>Prepare o vocabulário</h3><ul>'+v.words.map(([en,pt])=>'<li><span lang="en">'+esc(en)+'</span> — '+esc(pt)+'</li>').join('')+'</ul><fieldset><legend>Compreensão da entrevista</legend><p>'+esc(v.question)+'</p>'+v.options.map((o,j)=>'<label class="option"><input type="radio" name="authentic-answer" value="'+j+'"><span>'+esc(o)+'</span></label>').join('')+'<button type="button" class="btn soft" data-authentic-check="'+index+'">Conferir escuta real</button><p id="authentic-feedback" class="feedback" role="status"></p></fieldset><label for="authentic-notes">Seu caderno de escuta</label><p>Anote o minuto escolhido, a ideia principal, uma palavra difícil e uma pergunta que faria ao falante.</p><textarea id="authentic-notes" placeholder="Minuto: … Ideia: … Palavra: … Minha pergunta: …">'+esc(notes)+'</textarea><p id="authentic-save" class="muted" role="status">Suas anotações são salvas neste navegador. Esta prática é opcional e não altera os critérios de conclusão.</p><details><summary>Aplicar à situação da lição</summary><p>'+(index===1?'Em uma conversa com um fornecedor, pratique: <span lang="en">Could you repeat the quantity and confirm it in writing?</span> Confirme o que foi dito sem julgar a pronúncia.':'Em uma reunião de equipe, pratique: <span lang="en">Let me check I understood the opportunity and the main risk.</span> Faça uma pergunta específica sobre o trecho incerto.')+'</p></details><p class="muted">Título original: '+esc(v.title)+'. <a href="'+esc(v.reference)+'" target="_blank" rel="noopener noreferrer">Contexto publicado pelo organizador ↗</a>. Atividades elaboradas pelo ISM. O material externo é complementar e não implica parceria ou endosso.</p></section>';}
 function load(index,container){const v=sources[index];if(!v||!container)return;window.ISMAudio?.stop();const iframe=document.createElement('iframe');iframe.src='https://www.youtube-nocookie.com/embed/'+v.id+'?playsinline=1&cc_lang_pref=en';iframe.title=v.title;iframe.className='authentic-video';iframe.allow='encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';const close=document.createElement("button");close.type="button";close.className="btn soft";close.textContent="Fechar entrevista";close.onclick=()=>{const retry=document.createElement("button");retry.type="button";retry.className="btn";retry.textContent="Carregar entrevista original";retry.dataset.authenticLoad=String(index);container.replaceChildren(retry);};container.replaceChildren(iframe,close);}
 function check(index,value){const v=sources[index];if(!v)return '';if(value===null)return 'Escolha uma alternativa após ouvir o trecho correspondente.';return (Number(value)===v.answer?'✓ Correto. ':'Ouça novamente e tente outra vez. ')+v.feedback;}
 return {render,load,check};
})();

